// coupled-subsystem simulation sketch for: Extreme Conditions Reality Simulator
const subs = [
  {name:'power', x:0.792, k:0.078},
  {name:'thermal', x:0.826, k:0.099},
  {name:'structural', x:0.567, k:0.179},
];
for (let t = 0; t < 60; t++) {
  for (const s of subs) { s.x += s.k * (1 - s.x) - 0.015 * s.x; }
}
const fin = subs.map(s => +s.x.toFixed(4));
console.log(JSON.stringify({subsystems: subs.length, steps: 60,
  finalState: fin, converged: fin.every(v => v > 0 && v < 1.5),
  topic: 'Extreme Conditions Reality Simulator'}));

